    "#applying ceemden algorithm on processed dataset to remove noise and reconstruct signal\n",
    "ceemdan = CEEMDAN(parallel=True)\n",
    "if os.path.exists(\"model/cee_X.npy\"): #if already ceemden applied then load it\n",
    "    cee_X = np.load(\"model/cee_X.npy\")\n",
