    "testData = scaler.transform(testData)#normalizing dataset features\n",
    "cee = []\n",
    "for i in range(len(testData)):\n",
    "    IMFs = ceemdan(testData[i])#applyng ceemdan to process signals\n",
    "    cee.append(IMFs[0])    \n",
